// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        // Only allow the CEO address as caller
        vm.assume(caller == c.ceoAddress());

        // Record the original CEO address
        address originalCEO = c.ceoAddress();

        // Call DrugDealer() from the CEO address
        vm.prank(caller);
        c.DrugDealer();

        // Assert that the CEO address is now the caller (msg.sender)
        assertTrue(c.ceoAddress() == caller);
    }
}

